if (!sequence) {
  throw new Error("sequence should be defined");
}
var Engine = Packages.com.twinsoft.convertigo.engine.Engine;
var SchemaMeta = Packages.com.twinsoft.convertigo.engine.enums.SchemaMeta;
var XmlSchemaUtils = Packages.com.twinsoft.convertigo.engine.util.XmlSchemaUtils;
var XMLUtils = Packages.com.twinsoft.convertigo.engine.util.XMLUtils;
var JSONObject = Packages.org.codehaus.jettison.json.JSONObject;
var JSONArray = Packages.org.codehaus.jettison.json.JSONArray;
var QName = Packages.javax.xml.namespace.QName;
var targetProject = Engine.theApp.databaseObjectsManager.getOriginalProjectByName("ConvertigoMCP");
if (!targetProject) {
  throw new Error("Project ConvertigoMCP not found");
}
var requestableObject = targetProject.getSequenceByName(sequence);
if (!requestableObject) {
  throw new Error("Sequence not found: " + sequence);
}
var xmlSchema = Engine.theApp.schemaManager.getSchemaForProject(targetProject.getName());
var schemaObject = SchemaMeta.getXmlSchemaObject(xmlSchema, requestableObject);
if (schemaObject == null) {
  throw new Error("No schema metadata for " + sequence);
}
var collection = SchemaMeta.getCollection(schemaObject);
if (collection == null) {
  throw new Error("Schema collection missing for " + sequence);
}
var namespace = xmlSchema.getTargetNamespace();
var requestElement = collection.getElementByQName(new QName(namespace, requestableObject.getName()));
var responseElementName = requestableObject.getXsdTypePrefix() + requestableObject.getName() + "Response";
var responseElement = collection.getElementByQName(new QName(namespace, responseElementName));
var requestDom = requestElement != null ? XmlSchemaUtils.getDomInstance(requestElement) : null;
var responseDom = responseElement != null ? XmlSchemaUtils.getDomInstance(responseElement) : null;
var requestJsonString = requestDom != null ? XMLUtils.XmlToJson(requestDom.getDocumentElement(), true, true) : "{}";
var responseJsonString = responseDom != null ? XMLUtils.XmlToJson(responseDom.getDocumentElement(), true, true) : "{}";
requestDocument = new JSONObject(requestJsonString);
responseDocument = new JSONObject(responseJsonString);
requestPayloadName = requestableObject.getName();
responsePayloadName = responseElementName;
targetRequestable = requestableObject;
requestModel = JSON.parse(requestJsonString);
responseModel = JSON.parse(responseJsonString);

include("js/schema_common.js");
    include("js/schema_overrides.js");

function sampleValueForType(type) {
  type = String(type || "string").toLowerCase();
  if (type.indexOf("bool") >= 0) { return false; }
  if (type.indexOf("int") >= 0 || type.indexOf("long") >= 0) { return 0; }
  if (type.indexOf("number") >= 0 || type.indexOf("double") >= 0 || type.indexOf("float") >= 0) { return 0; }
  return "";
}

function normalizeNode(value) {
  if (value === null || value === undefined) { return null; }
  if (Array.isArray(value)) {
    if (value.length === 0) { return []; }
    return [ normalizeNode(value[0]) ];
  }
  if (typeof value === "object") {
    var result = {};
    var keys = Object.keys(value);
    for (var i = 0; i < keys.length; i++) {
      var key = keys[i];
      if (key === "attr" || key === "text") { continue; }
      var child = value[key];
      if (child && typeof child === "object" && child.attr && child.attr.originalKeyName) {
        var newKey = child.attr.originalKeyName || key;
        result[newKey] = sampleValueForType(child.attr.type);
        continue;
      }
      result[key] = normalizeNode(child);
    }
    if (result.error && typeof result.error === "object" && Object.keys(result.error).length === 0) {
      delete result.error;
    }
    return result;
  }
  return value;
}

function buildSchemaNode(value) {
  return C8O.schemaCommon.jsonSampleToSchema(value);
}

function pruneInternalKeys(value) {
  if (value === null || value === undefined) { return value; }
  if (Array.isArray(value)) {
    if (value.length === 0) { return value; }
    value[0] = pruneInternalKeys(value[0]);
    return value;
  }
  if (typeof value === "object") {
    var keys = Object.keys(value);
    for (var i = 0; i < keys.length; i++) {
      var key = keys[i];
      if (key && key.charAt && key.charAt(0) === "_") {
        delete value[key];
        continue;
      }
      value[key] = pruneInternalKeys(value[key]);
    }
  }
  return value;
}

function extractPayloadNode(model, key) {
  if (!model) { return null; }
  var container = model.document || model;
  return container ? container[key] : null;
}

var requestSource = extractPayloadNode(requestModel, requestPayloadName);
if (requestSource == null) { requestSource = {}; }
var normalizedRequest = normalizeNode(requestSource);
normalizedRequest = pruneInternalKeys(normalizedRequest);
inputSchemaJson = buildSchemaNode(normalizedRequest);
if (inputSchemaJson && typeof inputSchemaJson === "object") { inputSchemaJson.additionalProperties = false; }

var sequenceKey = String(sequence || "").trim().toLowerCase();
if (typeof C8O !== "undefined" && C8O.schemaOverrides && typeof C8O.schemaOverrides.applyInput === "function") {
  inputSchemaJson = C8O.schemaOverrides.applyInput(sequence, inputSchemaJson, targetRequestable);
}
if (typeof C8O !== "undefined" && C8O.schemaOverrides && typeof C8O.schemaOverrides.decorateInput === "function") {
  inputSchemaJson = C8O.schemaOverrides.decorateInput(sequenceKey, inputSchemaJson, targetRequestable);
}

var responseSource = extractPayloadNode(responseModel, responsePayloadName);
if (responseSource == null) { responseSource = responseModel; }
if (responseSource && responseSource.response) { responseSource = responseSource.response; }
if (responseSource && responseSource.result) { responseSource = responseSource.result; }
var normalizedResponse = normalizeNode(responseSource);
schemaJson = buildSchemaNode(normalizedResponse);
if (typeof C8O !== "undefined" && C8O.schemaOverrides && typeof C8O.schemaOverrides.applyOutput === "function") {
  schemaJson = C8O.schemaOverrides.applyOutput(sequence, schemaJson, targetRequestable, normalizedResponse);
}
if (typeof C8O !== "undefined" && C8O.schemaOverrides && typeof C8O.schemaOverrides.decorateOutput === "function") {
  schemaJson = C8O.schemaOverrides.decorateOutput(sequenceKey, schemaJson, targetRequestable, normalizedResponse);
}
if (schemaJson && typeof schemaJson === "object") {
  delete schemaJson.required;
}
exampleJson = normalizedResponse;
